#include <bits/stdc++.h>
using namespace std;using U=__uint128_t;using L=long long;
string dec(U x){if(!x)return "0";string s;while(x){s+='0'+x%10;x/=10;}reverse(s.begin(),s.end());return s;}
struct Eval{int n,N; vector<int> out; vector<L> en,st; Eval(int n):n(n),N(1<<n),out(n),en(N*n),st(N*n){} L run(U code){fill(out.begin(),out.end(),0);int t=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,t++)if(code>>t&1)out[i]|=1<<j;else out[j]|=1<<i;fill(en.begin(),en.end(),0);fill(st.begin(),st.end(),0);for(int i=0;i<n;i++)en[(1<<i)*n+i]=st[(1<<i)*n+i]=1;for(int S=1;S<N;S++){int z=S;while(z){int v=__builtin_ctz(z);z&=z-1;int P=S^(1<<v);if(!P)continue;int a=P&out[v],b=P&~out[v];while(a){int w=__builtin_ctz(a);a&=a-1;st[S*n+v]+=st[P*n+w];}while(b){int w=__builtin_ctz(b);b&=b-1;en[S*n+v]+=en[P*n+w];}}}L h=0;for(int i=0;i<n;i++)h+=en[(N-1)*n+i];return h;}
vector<L> deltas(){vector<L>d(n*(n-1)/2);int k=0;for(int u=0;u<n;u++)for(int v=u+1;v<n;v++,k++){L uv=0,vu=0;int rest=(N-1)^(1<<u)^(1<<v);for(int s=rest;;s=(s-1)&rest){int A=s|(1<<u),B=(N-1)^A;uv+=en[A*n+u]*st[B*n+v];A=s|(1<<v);B=(N-1)^A;vu+=en[A*n+v]*st[B*n+u];if(!s)break;}d[k]=(out[u]>>v&1)?vu-uv:uv-vu;}return d;}};
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):13,restarts=argc>2?atoi(argv[2]):100;L target=argc>3?atoll(argv[3]):759375;if(n<2||n>16||restarts<1)return 2;mt19937_64 rng(20813);Eval e(n);int m=n*(n-1)/2;L best=LLONG_MAX;for(int r=0;r<restarts;r++){U code=((U(rng())<<64)|rng())&((U(1)<<m)-1);for(int step=0;step<100;step++){L h=e.run(code),err=abs(h-target);if(err<best){best=err;cerr<<"best "<<n<<" "<<target<<" "<<h<<" "<<err<<" "<<r<<" "<<step<<endl;}if(h==target){cout<<n<<" "<<h<<" "<<dec(code)<<" "<<r<<" "<<step<<endl;return 0;}auto d=e.deltas();vector<int> moves;L next=LLONG_MAX;for(int j=0;j<m;j++){L v=abs(h+d[j]-target);if(v<next)next=v,moves.clear();if(v==next)moves.push_back(j);}int j=moves[rng()%moves.size()];if(next>=err){if(step>60)break;j=rng()%m;}L expect=h+d[j];code^=U(1)<<j;L got=e.run(code);if(got!=expect){cerr<<"bad delta\n";return 3;}}}return 1;}
